"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15578"],{352(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.obrigatoriedade_legal.regra_codigo_duplicada","status":409,"titulo":"J\xe1 existe regra ativa com este RegraCodigo"},"descricao":{"codigo":"uniplus.selecao.obrigatoriedade_legal.regra_codigo_duplicada","requisitos":[],"oQueAconteceu":["O c\xf3digo de regra informado j\xe1 pertence a outra obrigatoriedade legal **ativa**. O c\xf3digo identifica\\na regra, e duas regras vigentes com o mesmo c\xf3digo tornariam amb\xedgua a refer\xeancia a ela. A mensagem\\nda resposta n\xe3o repete o c\xf3digo informado. Nada \xe9 gravado.","A compara\xe7\xe3o \xe9 exata, com diferen\xe7a entre mai\xfasculas e min\xfasculas, depois de aparar os espa\xe7os das\\npontas. S\xf3 regra ativa conta: o c\xf3digo de uma regra desativada fica livre para uso. Na atualiza\xe7\xe3o, a\\npr\xf3pria regra \xe9 desconsiderada, de modo que ela pode manter o c\xf3digo que j\xe1 tem.","A confer\xeancia vem depois da leitura do corpo, da confer\xeancia dos campos (entre eles, o pr\xf3prio c\xf3digo\\nde regra:\\n[`regra_codigo_obrigatorio`](/erros/uniplus.selecao.obrigatoriedade_legal.regra_codigo_obrigatorio) e\\n[`regra_codigo_invalido`](/erros/uniplus.selecao.obrigatoriedade_legal.regra_codigo_invalido)), de, na\\natualiza\xe7\xe3o, a regra ser encontrada\\n([`nao_encontrada`](/erros/uniplus.selecao.obrigatoriedade_legal.nao_encontrada)), e da do tipo de\\nprocesso\\n([`tipo_processo_nao_encontrado_ou_inativo`](/erros/uniplus.selecao.obrigatoriedade_legal.tipo_processo_nao_encontrado_ou_inativo))\\ne das refer\xeancias do predicado, e antes da grava\xe7\xe3o.","Duas escritas simult\xe2neas com o mesmo c\xf3digo podem passar juntas pela confer\xeancia. Nesse caso \xe9 o\\nbanco de dados que recusa a segunda, e a resposta \xe9 esta mesma, com status 409: a corrida n\xe3o resulta\\nem erro interno do servidor. Se o conte\xfado das duas for id\xeantico,\\na recusa pode vir como\\n[`hash_colisao`](/erros/uniplus.selecao.obrigatoriedade_legal.hash_colisao)."],"comoResolver":["Escolha outro c\xf3digo de regra. Se a inten\xe7\xe3o \xe9 alterar a regra que j\xe1 usa o c\xf3digo, atualize-a em\\nvez de criar outra. Se a regra existente deve ser substitu\xedda, desative-a antes e crie a nova."],"ondeAparece":["Cadastro de uma obrigatoriedade legal","Atualiza\xe7\xe3o de uma obrigatoriedade legal"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Obrigatoriedade legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);